#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::istringstream in(line);
        std::string surname, name, patronymic;
        in >> surname >> name >> patronymic;
        std::string result = surname + " " + name[0] + ".";
        if (!patronymic.empty()) {
            result += " ";
            result += patronymic[0];
            result += ".";
        }
        std::cout << result << '\n';
    }
    return 0;
}

