#include <iostream>
#include <string>

int main() {
    std::string from, to;
    if (!(std::cin >> from >> to)) {
        return 0;
    }
    std::string line;
    std::getline(std::cin, line);
    while (std::getline(std::cin, line)) {
        std::size_t pos = line.find(from);
        while (pos != std::string::npos) {
            line.replace(pos, from.size(), to);
            pos = line.find(from, pos + to.size());
        }
        std::cout << line << '\n';
    }
    return 0;
}

